import { useState } from "react"
import { Input } from "@/registry/default/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/registry/default/ui/select"
import { Button } from "@/registry/default/ui/button"

const cx = (...parts: unknown[]) => parts.filter((p): p is string => typeof p === "string").join(" ")

export interface FilterBarProps {
  search?: string
  onSearchChange?: (value: string) => void
  filters?: Array<{
    key: string
    placeholder: string
    options: string[]
    value?: string
    onChange?: (value: string | undefined) => void
  }>
  onReset?: () => void
  className?: string
}

export function FilterBar({ search, onSearchChange, filters = [], onReset, className }: FilterBarProps) {
  const [localSearch, setLocalSearch] = useState("")

  const searchValue = search ?? localSearch
  const handleSearch = (v: string) => {
    setLocalSearch(v)
    onSearchChange?.(v)
  }

  return (
    <div data-slot="filter-bar" className={cx("raya-filter-bar", className)} role="search">
      <Input
        type="search"
        placeholder="Search…"
        value={searchValue}
        onChange={(e) => handleSearch(e.target.value)}
        style={{ maxWidth: "14rem" }}
      />
      {filters.map((f) => (
        <Select
          key={f.key}
          value={f.value ?? null}
          onValueChange={(v) => f.onChange?.((v as string | null) ?? undefined)}
          items={f.options.map((o) => ({ label: o, value: o }))}
        >
          <SelectTrigger style={{ width: "9.5rem" }}>
            <SelectValue placeholder={f.placeholder} />
          </SelectTrigger>
          <SelectContent>
            {f.options.map((o) => (
              <SelectItem key={o} value={o}>
                {o}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      ))}
      {onReset && (
        <Button onClick={onReset} className="ml-auto">
          Reset
        </Button>
      )}
    </div>
  )
}

import { useMemo, useState } from "react"
import { FilterBar } from "./filter-bar"

const ROWS = [
  { id: "SHP-1042", customer: "Northwind Labs", plan: "Scale", status: "active", mrr: 1240 },
  { id: "SHP-1017", customer: "Acme Foundry", plan: "Growth", status: "trial", mrr: 420 },
  { id: "SHP-1088", customer: "Bluepeak Systems", plan: "Starter", status: "active", mrr: 99 },
  { id: "SHP-1103", customer: "Cobalt & Sons", plan: "Scale", status: "past_due", mrr: 1240 },
  { id: "SHP-1121", customer: "Driftwood AI", plan: "Growth", status: "active", mrr: 460 },
]

export function DemoFilterBar() {
  const [search, setSearch] = useState("")
  const [plan, setPlan] = useState<string | undefined>()
  const [status, setStatus] = useState<string | undefined>()

  const filtered = useMemo(
    () =>
      ROWS.filter(
        (r) =>
          r.customer.toLowerCase().includes(search.toLowerCase()) &&
          (!plan || r.plan === plan) &&
          (!status || r.status === status),
      ),
    [search, plan, status],
  )

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem", fontFamily: "var(--font-sans)" }}>
      <FilterBar
        search={search}
        onSearchChange={setSearch}
        filters={[
          { key: "plan", placeholder: "Plan", options: ["Starter", "Growth", "Scale"], value: plan, onChange: setPlan },
          { key: "status", placeholder: "Status", options: ["active", "trial", "past_due"], value: status, onChange: setStatus },
        ]}
        onReset={() => {
          setSearch("")
          setPlan(undefined)
          setStatus(undefined)
        }}
      />
      <span className="text-xs text-muted-foreground">
        Showing {filtered.length} of {ROWS.length} demo rows — wire `filters` to your own table state in production.
      </span>
      <table className="raya-table">
        <thead>
          <tr>
            {["ID", "Customer", "Plan", "Status", "MRR"].map((h) => (
              <th key={h}>{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {filtered.map((r) => (
            <tr key={r.id}>
              <td>{r.id}</td>
              <td>{r.customer}</td>
              <td>{r.plan}</td>
              <td>{r.status}</td>
              <td>${r.mrr}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

export { FilterBar }
